import json, sys, os
os.chdir(os.path.dirname(os.path.abspath(__file__)))
for f in ["run-A-capped.json", "run-A-approved.json", "run-B-capped.json", "run-B-denied.json"]:
    p = json.load(open(f))
    calls, order = {}, []
    for x in p:
        if x["type"] == "tool-input-available":
            inp = x["input"] if isinstance(x["input"], dict) else {}
            calls[x["toolCallId"]] = [x["toolName"], inp.get("path"), None]
            order.append(x["toolCallId"])
        if x["type"] == "tool-output-available" and x["toolCallId"] in calls:
            o = x["output"]
            if isinstance(o, dict) and "subAgentThreadId" in o:
                reads = ", ".join(
                    "%s(%d)" % ((r.get("args") or {}).get("path") or r.get("toolName"), len(json.dumps(r.get("result"))))
                    for r in o.get("subAgentToolResults", [])
                )
                calls[x["toolCallId"]][2] = "text=%d chars; reads: %s" % (len(o.get("text", "")), reads or "none")
            else:
                calls[x["toolCallId"]][2] = "%d chars" % len(json.dumps(o))
    u = [x for x in p if x["type"] == "data-turn-usage"][-1]["data"]
    print("##", f, {k: u.get(k) for k in ("costUsd", "tokens", "steps", "trippedBy", "traceId")})
    for c in order:
        print("  -", *calls[c])

